$ErrorActionPreference = "Stop"

$ProjectRoot = (Get-Location).Path
$PackagePath = Join-Path $ProjectRoot "package.json"
$P03Path = Join-Path $ProjectRoot ".private\entity\build\P03\evidence-packets.json"
$CompilerPath = Join-Path $ProjectRoot "scripts\entity\build-cached-emet-explanations.js"
$BatchPath = Join-Path $ProjectRoot "scripts\entity\batch-cached-emet-explanations.js"
$SchedulerPath = Join-Path $ProjectRoot "scripts\entity\schedule-cached-emet-generation.js"
$PromptPath = Join-Path $ProjectRoot "scripts\entity\emet-prompts\emet-free-tier-v1.js"
$EnvPath = Join-Path $ProjectRoot ".env.local"
$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupRoot = Join-Path $ProjectRoot ".private\entity\backups\P04-tier1-scheduler-$Timestamp"

$CompilerPayload = ""
$BatchPayload = ""
$SchedulerPayload = ""
$PromptPayload = ""

function Write-Payload {
    param([Parameter(Mandatory)][string]$Payload, [Parameter(Mandatory)][string]$Path)
    $directory = Split-Path -Parent $Path
    New-Item -ItemType Directory -Force -Path $directory | Out-Null
    [System.IO.File]::WriteAllBytes($Path, [Convert]::FromBase64String($Payload))
}

function Backup-File {
    param([Parameter(Mandatory)][string]$Path)
    if (-not (Test-Path $Path)) { return }
    $relative = $Path.Substring($ProjectRoot.Length).TrimStart('\', '/')
    $destination = Join-Path $BackupRoot $relative
    New-Item -ItemType Directory -Force -Path (Split-Path -Parent $destination) | Out-Null
    Copy-Item -Force $Path $destination
}

function Restore-Backup {
    if (-not (Test-Path $BackupRoot)) { return }
    Get-ChildItem -Path $BackupRoot -File -Recurse | ForEach-Object {
        $relative = $_.FullName.Substring($BackupRoot.Length).TrimStart('\', '/')
        $destination = Join-Path $ProjectRoot $relative
        New-Item -ItemType Directory -Force -Path (Split-Path -Parent $destination) | Out-Null
        Copy-Item -Force $_.FullName $destination
    }
}

function Add-EnvSettingIfMissing {
    param([Parameter(Mandatory)][string]$Name, [Parameter(Mandatory)][string]$Value)
    if (-not (Test-Path $EnvPath)) {
        [System.IO.File]::WriteAllText($EnvPath, "", (New-Object System.Text.UTF8Encoding($false)))
    }
    $content = Get-Content $EnvPath -Raw
    $pattern = "(?m)^\s*" + [regex]::Escape($Name) + "\s*="
    if ($content -match $pattern) { return }
    $updated = $content.TrimEnd() + "`r`n$Name=$Value`r`n"
    [System.IO.File]::WriteAllText($EnvPath, $updated, (New-Object System.Text.UTF8Encoding($false)))
}

if (-not (Test-Path $PackagePath)) { throw "package.json was not found. Run this installer from the ai-bible-app project root." }
if (-not (Test-Path $P03Path)) { throw "P03 evidence-packets.json was not found. Complete P03 before installing the P04 scheduler." }

New-Item -ItemType Directory -Force -Path $BackupRoot | Out-Null
foreach ($path in @($PackagePath, $CompilerPath, $BatchPath, $SchedulerPath, $PromptPath, $EnvPath)) { Backup-File $path }

try {
    Write-Host "Installing P04 Tier-safe scheduler v1.3.0..." -ForegroundColor Cyan
    Write-Payload $CompilerPayload $CompilerPath
    Write-Payload $BatchPayload $BatchPath
    Write-Payload $SchedulerPayload $SchedulerPath
    Write-Payload $PromptPayload $PromptPath

    $package = Get-Content $PackagePath -Raw | ConvertFrom-Json
    if (-not $package.scripts) { $package | Add-Member -MemberType NoteProperty -Name scripts -Value ([pscustomobject]@{}) }
    $scripts = [ordered]@{}
    foreach ($property in $package.scripts.PSObject.Properties) { $scripts[$property.Name] = $property.Value }
    $scripts["build:cached-emet"] = "node --max-old-space-size=4096 scripts/entity/build-cached-emet-explanations.js"
    $scripts["verify:cached-emet"] = "node --max-old-space-size=4096 scripts/entity/build-cached-emet-explanations.js --verify"
    $scripts["batch:cached-emet"] = "node --max-old-space-size=4096 scripts/entity/batch-cached-emet-explanations.js"
    $scripts["prepare:cached-emet-batch"] = "node --max-old-space-size=4096 scripts/entity/batch-cached-emet-explanations.js --prepare"
    $scripts["submit:cached-emet-batch"] = "node --max-old-space-size=4096 scripts/entity/batch-cached-emet-explanations.js --submit"
    $scripts["status:cached-emet-batch"] = "node --max-old-space-size=4096 scripts/entity/batch-cached-emet-explanations.js --status"
    $scripts["import:cached-emet-batch"] = "node --max-old-space-size=4096 scripts/entity/batch-cached-emet-explanations.js --import"
    $scripts["verify:cached-emet-batch"] = "node --max-old-space-size=4096 scripts/entity/batch-cached-emet-explanations.js --verify"
    $scripts["cancel:cached-emet-batch"] = "node --max-old-space-size=4096 scripts/entity/batch-cached-emet-explanations.js --cancel"
    $scripts["emet:generate"] = "node --max-old-space-size=4096 scripts/entity/schedule-cached-emet-generation.js --run"
    $scripts["emet:generate:plan"] = "node --max-old-space-size=4096 scripts/entity/schedule-cached-emet-generation.js --plan"
    $scripts["emet:generate:status"] = "node --max-old-space-size=4096 scripts/entity/schedule-cached-emet-generation.js --status"
    $scripts["emet:generate:watch"] = "node --max-old-space-size=4096 scripts/entity/schedule-cached-emet-generation.js --run --watch"
    $scripts["emet:generate:reset"] = "node --max-old-space-size=4096 scripts/entity/schedule-cached-emet-generation.js --reset"
    $package.scripts = [pscustomobject]$scripts
    $json = $package | ConvertTo-Json -Depth 100
    [System.IO.File]::WriteAllText($PackagePath, $json + "`r`n", (New-Object System.Text.UTF8Encoding($false)))

    Add-EnvSettingIfMissing "EMET_P04_TIER_DAILY_TOKEN_LIMIT" "2000000"
    Add-EnvSettingIfMissing "EMET_P04_SCHEDULER_TOKEN_BUDGET" "1600000"
    Add-EnvSettingIfMissing "EMET_P04_SCHEDULER_REQUEST_SIZE" "1"
    Add-EnvSettingIfMissing "EMET_P04_SCHEDULER_COOLDOWN_HOURS" "24"
    Add-EnvSettingIfMissing "EMET_P04_OUTPUT_TOKEN_RESERVE" "600"

    & node --check $CompilerPath
    if ($LASTEXITCODE -ne 0) { throw "P04 compiler syntax validation failed." }
    & node --check $BatchPath
    if ($LASTEXITCODE -ne 0) { throw "P04 Batch compiler syntax validation failed." }
    & node --check $SchedulerPath
    if ($LASTEXITCODE -ne 0) { throw "P04 scheduler syntax validation failed." }
    & node --check $PromptPath
    if ($LASTEXITCODE -ne 0) { throw "P04 prompt syntax validation failed." }

    Write-Host "`nInspecting the final P04 scheduler plan (no API request)..." -ForegroundColor Cyan
    & npm run emet:generate:plan
    if ($LASTEXITCODE -ne 0) { throw "P04 scheduler plan failed." }

    Write-Host "`nP04 Tier-safe scheduler installed successfully." -ForegroundColor Green
    Write-Host "Backup: $BackupRoot"
    Write-Host "`nNext command:"
    Write-Host "npm run emet:generate" -ForegroundColor Yellow
}
catch {
    Write-Host "`nInstallation failed. Restoring the previous files..." -ForegroundColor Red
    Restore-Backup
    throw
}
